	get creationDate() {
		return this.dict.getString("CreationDate", this.registry.resolve.bind(this.registry))?.asString() ?? null;
	}
	/**
	* Set the creation date.
	*/
	setCreationDate(date) {
		this.dict.set("CreationDate", PdfString.fromString(date));
		this.markModified();
	}
