	setJustification(justification) {
		let val = 0;
		if (justification === "center") val = 1;
		else if (justification === "right") val = 2;
		this.dict.set("Q", PdfNumber.of(val));
		this.markModified();
	}
	/**
	* Default style string (DS).
	* Contains CSS-style formatting.
	*/
	get defaultStyle() {
		return this.dict.getString("DS", this.registry.resolve.bind(this.registry))?.asString() ?? null;
	}
