function buildFormXObject(ctx, content, width, height, font, fontName, widget) {
	const resources = buildFontResources(font, fontName);
	const matrix = calculateAppearanceMatrix(width, height, widget.getAppearanceCharacteristics()?.rotation ?? 0);
	return content.toFormXObject([
		0,
		0,
		width,
		height
	], resources, matrix);
}
function calculateAppearanceMatrix(width, height, rotation) {
	switch (Math.abs(rotation)) {
		case 90: return [
			0,
			1,
			-1,
			0,
			height,
			0
		];
		case 180: return [
			-1,
			0,
			0,
			-1,
			width,
			height
		];
		case 270: return [
			0,
			-1,
			1,
			0,
			0,
			width
		];
		default: return;
	}
}

