//#region src/helpers/save-utils.ts
/**
* Check if a document can be saved incrementally.
*
* Returns null if incremental save is possible, or a blocker reason if not.
*/
function checkIncrementalSaveBlocker(context) {
	if (context.isNewlyCreated) return "newly-created";
	if (context.isLinearized) return "linearized";
	if (context.recoveredViaBruteForce) return "brute-force-recovery";
	if (context.encryptionAdded) return "encryption-added";
	if (context.encryptionRemoved) return "encryption-removed";
	if (context.encryptionChanged) return "encryption-changed";
	return null;
}

